      if(Number(ss.energyDiscard?.[type]||0)>0){ss.energyDiscard[type]--;taken++;continue;}
      const idx=(ss.discard||[]).findIndex(ref=>{const c=ctx.cardById(ref.cardId);return c?.basicEnergy&&c.subtype===type;});
      if(idx<0)break;
