      card=ref=>ctx.cardById(ref?.cardId),my=pokemonOn(us),theirs=pokemonOn(foe),atk=ctx.cardById('ex15-'+n)?.attacks?.[Number(part)||0];
    const pick=(kind,opts={})=>ctx.requestChoice?.({kind,side:'self',optional:true,effect:e,...opts});
