          if(ent.kind==='zone'){if(!us.energyDiscard?.[ent.type])return;us.energyDiscard[ent.type]--;us.hand.push({uid:'ex12-power-tree-'+turn+'-'+us.hand.length,cardId:neoBasicIds[ent.type]});}
