    const flip=()=>{const h=coin(ctx);ctx.state.log.push({type:'coin',side:ctx.side,heads:h,reason:'EX Delta Species '+key});return h;};
    const shuffle=()=>ctx.shuffle?.(ctx.state,us.deck);
