      if(e.stage==='pick'&&ctx.resolvingChoice){const i=choiceIndex();if(i>=waters.length){ss.discard.push(...seen);return;}const ref=waters[i];return askPokemon('target',false,true,false,{energyUid:ref.uid,reveal:seen});}
