    const discardAttached=(owner,slot)=>{for(const [type,n] of Object.entries(slot?.energy||{})){recordDiscardedEnergy(owner,type,Number(n||0));slot.energy[type]=0;}owner.discard.push(...(slot?.specialEnergy||[]));slot.specialEnergy=[];};
