          const added=[...selection,ref.uid];if(added.length<2){const next=ss.hand.filter(r=>!added.includes(r.uid));if(next.length)ask(next.map(x=>({ref:x,label:'Discard '+card(x)?.name})),'discard',{selected:added});return;}
