      energyIn=slot=>[...Object.entries(slot?.energy||{}).filter(([,count])=>Number(count)>0).map(([type,count])=>({type,count,label:type+' Basic Energy'})),
        ...(slot?.specialEnergy||[]).map(ref=>({ref,label:card(ref)?.name||'Special Energy'}))],
