        eligible=()=>ownAll().filter(p=>card(p)?.stage==='Basic'&&(Number(p.playedOnSideTurn||0)<Number(us.turnCount||0))&&us.hand.some(r=>card(r)?.name===evolutions[card(p)?.name]&&card(r)?.stage==='Stage 2'));
